package cmdopts_test

import (
	"path/filepath"
	"testing"

	"github.com/egdaemon/eg"
	"github.com/egdaemon/eg/cmd/cmdopts"
	"github.com/egdaemon/eg/internal/userx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestDefaultSSHKeyPath(t *testing.T) {
	t.Run("honors EG_SSH_PATH", func(t *testing.T) {
		t.Setenv(eg.EnvEGSSHPath, "/custom/path/ssh_key")
		require.Equal(t, "/custom/path/ssh_key", cmdopts.DefaultSSHKeyPath())
	})

	t.Run("honors CONFIGURATION_DIRECTORY", func(t *testing.T) {
		t.Setenv(eg.EnvEGSSHPath, "")
		t.Setenv("CONFIGURATION_DIRECTORY", "/custom/config")
		require.Equal(t, filepath.Join("/custom/config", userx.DefaultDir), cmdopts.DefaultSSHKeyPath())
	})

	t.Run("uses home directory fallback", func(t *testing.T) {
		t.Setenv(eg.EnvEGSSHPath, "")
		t.Setenv("CONFIGURATION_DIRECTORY", "")
		result := cmdopts.DefaultSSHKeyPath()
		require.True(t, filepath.IsAbs(result))
		require.Equal(t, userx.DefaultDir, filepath.Base(result))
		require.Contains(t, result, ".ssh")
	})
}
